#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
    double x[5][3]={{1,1,0},{1,2,1},{1,3,0},{1,4,1},{1,5,0}},y[5]={2,4,5,7,8};
    double a[3][4]={};
    for (int i=0;i<5;i++)for (int j=0;j<3;j++){
        a[j][3]+=x[i][j]*y[i];
        for (int k=0;k<3;k++)a[j][k]+=x[i][j]*x[i][k];
    }
    for (int i=0;i<3;i++){
        int best=i;
        for (int j=i+1;j<3;j++)if (fabs(a[j][i])>fabs(a[best][i]))best=j;
        if (fabs(a[best][i])<1e-10)return 1;
        for (int k=0;k<4;k++)swap(a[best][k],a[i][k]);
        double p=a[i][i];
        for (int k=i;k<4;k++)a[i][k]/=p;
        for (int j=0;j<3;j++)if (j!=i){
            double w=a[j][i];
            for (int k=i;k<4;k++)a[j][k]-=w*a[i][k];
        }
    }
    for (int i=0;i<3;i++)cout<<a[i][3]<<" ";
    cout<<"\n";
    return 0;
}

