#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
    vector<double>x={1,2,3,4,5},y={2,4,4,7,8};
    double mx=3,my=5,sxx=0,sxy=0;
    for (int i=0;i<5;i++){
        sxx+=pow(x[i]-mx,2);
        sxy+=(x[i]-mx)*(y[i]-my);
    }
    double beta=sxy/sxx,intercept=my-beta*mx,rss=0;
    for (int i=0;i<5;i++)rss+=pow(y[i]-intercept-beta*x[i],2);
    double se=sqrt((rss/3)/sxx);
    cout<<beta-1.96*se<<" "<<beta+1.96*se<<"\n";
    return 0;
}

